CREATE OR REPLACE FUNCTION public.social_post_chain_visible(_post uuid,_visited uuid[] DEFAULT '{}'::uuid[]) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; BEGIN IF _post=ANY(_visited) OR cardinality(_visited)>=16 THEN RETURN false; END IF; SELECT * INTO p FROM public.posts WHERE id=_post; IF NOT FOUND THEN RETURN false; END IF; RETURN (p.user_id=auth.uid() OR (p.moderation_status='approved' AND public.social_audience_visible(p.user_id,p.visibility))) AND (p.collectible_id IS NULL OR public.social_vault_card_visible(p.collectible_id)) AND (p.image_url IS NULL OR p.image_url NOT LIKE '%/vault-images/%' OR public.social_vault_media_visible(split_part(p.image_url,'/vault-images/',2))) AND (p.shared_post_id IS NULL OR public.social_post_chain_visible(p.shared_post_id,array_append(_visited,_post))); END $$;
COMMENT ON FUNCTION public.social_post_chain_visible(uuid,uuid[]) IS 'DRAFT ONLY: referenced private content must be authorized even for repost author; cycles/depth >16 fail closed.';